cd /home/daniel/ui-work/runs/202610271-to/sandbox/officehq-tanstack-officefloor; python3 - <<'EOF'
p='src/main/java/net/officefloor/hq/app/claim/ClaimStore.java'
s=open(p).read()
anchor='''    /** Takes the next number in one of the sheet's per-period sequences'''
add='''    /** Takes the next claim number in the sheet-wide sequence the sheets of a tree share: one after the last number
     *  given on any of them (the sheet is among {@code tree}). Each sheet keeps its own counter, so the last number
     *  given is the largest of theirs; the counters are locked, in id order, until the transaction ends, as
     *  {@link #nextNumber(String)} does. */
    public long nextNumber(String sheetId, java.util.Collection<String> tree) {
        java.util.SortedSet<String> ids = new java.util.TreeSet<>(tree);
        ids.add(sheetId);
        long last = 0;
        for (String id : ids) {
            try {
                jdbc.update("INSERT INTO claim_number (sheet_id, last_number) SELECT ?, 0 FROM DUAL "
                        + "WHERE NOT EXISTS (SELECT 1 FROM claim_number WHERE sheet_id = ?)", id, id);
            } catch (DataAccessException e) {
                // another transaction added the sheet's counter first
            }
            jdbc.update("UPDATE claim_number SET last_number = last_number WHERE sheet_id = ?", id);
            last = Math.max(last, jdbc.queryForObject("SELECT last_number FROM claim_number WHERE sheet_id = ?",
                    Long.class, id));
        }
        jdbc.update("UPDATE claim_number SET last_number = ? WHERE sheet_id = ?", last + 1, sheetId);
        return last + 1;
    }

'''
assert anchor in s
s=s.replace(anchor,add+anchor,1)
open(p,'w').write(s)

p='src/main/java/net/officefloor/hq/app/setting/SettingStore.java'
s=open(p).read()
anchor='''    /** Whether naming the parent for the sheet would make'''
add='''    /** Every sheet of the sheet's tree, the sheet among them: the topmost ancestor and all its descendants. The
     *  parents are those named now. */
    public List<String> wholeTree(String sheetId) {
        java.util.Set<String> seen = new java.util.HashSet<>(List.of(sheetId));
        String root = sheetId;
        for (String at = parent(sheetId); at != null && seen.add(at); at = parent(at)) {
            root = at;
        }
        java.util.Set<String> all = new java.util.LinkedHashSet<>(List.of(root));
        all.addAll(descendants(root));
        all.add(sheetId);
        return List.copyOf(all);
    }

'''
assert anchor in s
s=s.replace(anchor,add+anchor,1)
open(p,'w').write(s)

