s=s.replace(''' *  none. Otherwise it takes the sheet's next sheet-wide number (1, 2, ...), which carries on from
 *  where it left off. */''',''' *  none. Otherwise it takes the next sheet-wide number (1, 2, ...) of the sequence all the sheets of
 *  its tree share: one after the last number given on any of them. */''')
open(p,'w').write(s)
EOF
